import{f as e,j as t,m as n}from"./runtime-core.esm-bundler-DBPRRnSd.js";import{t as r}from"./plugin-vue_export-helper-CDQIAITX.js";var i=JSON.parse(`{"path":"/notes/%E9%9D%A2%E8%AF%95/netty/","title":"netty | notes","lang":"zh-CN","frontmatter":{"title":"netty","createTime":"2026/04/04 23:28:20","permalink":"/notes/面试/netty/","description":"几种I/O模型 同步阻塞（Blocking I/O，BIO） 线程调用read时，如果还没有接收到数据，线程会阻塞等待；数据从网卡 -&gt; 内核 -&gt; 用户空间，两个过程都为阻塞操作 缺点：每一个连接都需要一个线程，即使没有数据，线程也会被占用，导致资源浪费，不适合高并发场景 image-20250307155352223 同步非阻塞（Non...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"netty\\",\\"image\\":[\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250307160957869.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250307161011488.png\\",\\"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250307161024192.png\\"],\\"dateModified\\":\\"2026-06-25T07:15:35.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"http://xiaofei.site/notes/%E9%9D%A2%E8%AF%95/netty/"}],["meta",{"property":"og:site_name","content":"计算机知识杂货铺"}],["meta",{"property":"og:title","content":"netty"}],["meta",{"property":"og:description","content":"几种I/O模型 同步阻塞（Blocking I/O，BIO） 线程调用read时，如果还没有接收到数据，线程会阻塞等待；数据从网卡 -&gt; 内核 -&gt; 用户空间，两个过程都为阻塞操作 缺点：每一个连接都需要一个线程，即使没有数据，线程也会被占用，导致资源浪费，不适合高并发场景 image-20250307155352223 同步非阻塞（Non..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250307160957869.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-06-25T07:15:35.000Z"}],["meta",{"property":"article:modified_time","content":"2026-06-25T07:15:35.000Z"}]]},"readingTime":{"minutes":2.95,"words":886},"git":{"createdTime":1775331561000,"updatedTime":1782371735000,"contributors":[{"name":"xiaofei","username":"xiaofei","email":"tu_aofei@163.com","commits":1,"avatar":"https://avatars.githubusercontent.com/u/49927991?s=96&v=4","url":"https://github.com/731016"},{"name":"731016","username":"731016","email":"xiaofei00152@gmail.com","commits":1,"avatar":"https://avatars.githubusercontent.com/731016?v=4","url":"https://github.com/731016"}],"changelog":[{"hash":"6226c1c3cfce235348f612b9ec8a011caac82791","time":1782371735000,"email":"xiaofei00152@gmail.com","author":"731016","message":"更新侧边栏配置和图标"},{"hash":"fb8bc3afbb338138170b503192cbdb88a45075bd","time":1775331561000,"email":"tu_aofei@163.com","author":"xiaofei","message":"更新为vuepress"}]},"autoDesc":true,"filePathRelative":"notes/面试/netty.md","headers":[],"bulletin":true}`),a={name:`netty.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h2 id="几种i-o模型" tabindex="-1"><a class="header-anchor" href="#几种i-o模型"><span>几种I/O模型</span></a></h2><p>同步阻塞（Blocking I/O，BIO）</p><p>线程调用read时，如果还没有接收到数据，线程会阻塞等待；数据从网卡 -&gt; 内核 -&gt; 用户空间，两个过程都为阻塞操作</p><p>缺点：每一个连接都需要一个线程，即使没有数据，线程也会被占用，导致资源浪费，不适合高并发场景</p><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250307155352223.png" alt="image-20250307155352223" style="zoom:67%;"><p>同步非阻塞（Non-Blocking I/O，NIO）</p><p>read调用如果没数据，会立即返回错误（或特定状态），不会阻塞线程；应用程序需要不断轮询判断数据是否就绪。但数据从内核 -&gt; 用户空间还是阻塞的</p><p>缺点：轮询方式会频繁进行系统调用，上下文切换开销大，CPU占用较高，不适合大规模连接</p><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/notenoteimage-20250307155525325.png" alt="image-20250307155525325" style="zoom:67%;"><p>I/O多路复用</p><p>通过一个线程（或少量线程）监控多个连接的状态；只有某个连接的数据就绪时，系统才通知应用程序，再执行read读取操作</p><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250307155436153.png" alt="image-20250307155436153" style="zoom:67%;"><p>信号驱动 I/0</p><p>由内核在数据就绪时发出信号通知应用程序，应用程序收到信号，再执行read读取操作</p><p>缺点：对于TCP协议，由于同一个信号可能对应多种事件，难以精确区分（实际应用较少）</p><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250307155448331.png" alt="image-20250307155448331" style="zoom:67%;"><p>异步I/O （Asynchronous I/O，AIO）</p><p>调用aio_read后，内核负责将数据从网卡 -&gt; 内核 -&gt; 用户空间，拷贝完成后通过回调通知应用程序；整个过程线程没有阻塞</p><p>缺点：linux支持不完善</p><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250307155505751.png" alt="image-20250307155505751" style="zoom:67%;"><p><a href="https://www.mianshiya.com/bank/1804354610222800897/question/1804476796656885762" target="_blank" rel="noopener noreferrer">说说你知道的几种 I/O 模型 - Netty 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><h3 id="介绍一下reactor线程模型" tabindex="-1"><a class="header-anchor" href="#介绍一下reactor线程模型"><span>介绍一下Reactor线程模型</span></a></h3><p>基于事件驱动，将I/O操作抽象成不同的事件，每个事件都配置对应的回调函数，由Selector监听连接上事件的发生，再进行分发调用相应的回调函数进行处理</p><p>单Reactor单线程模型</p><p>所有操作都是一个I/O线程处理</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250307160957869.png" alt="image-20250307160957869" tabindex="0" loading="lazy"><figcaption>image-20250307160957869</figcaption></figure><p>单Reactor多线程模型</p><p>一个线程接收建立连接事件和后续的连接I/O处理，线程池处理具体业务逻辑</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250307161011488.png" alt="image-20250307161011488" tabindex="0" loading="lazy"><figcaption>image-20250307161011488</figcaption></figure><p>主从Reactor多线程模型</p><p>主Reactor负责接收建立连接事件，从Reactor负责处理后续的连接I/O处理，线程池处理具体业务逻辑</p><figure><img src="https://note-1259190304.cos.ap-chengdu.myqcloud.com/noteimage-20250307161024192.png" alt="image-20250307161024192" tabindex="0" loading="lazy"><figcaption>image-20250307161024192</figcaption></figure><h2 id="tcp粘包、半包" tabindex="-1"><a class="header-anchor" href="#tcp粘包、半包"><span>TCP粘包、半包</span></a></h2><p><a href="https://www.mianshiya.com/bank/1804354610222800897/question/1805367724032598017" target="_blank" rel="noopener noreferrer">说一下 TCP 半包和粘包问题？ - Netty 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>如果一次传输的数据大小没有超过发送缓冲区大小，完整的报文会被拆分，导致半包</p><p>如果一次传输的数据大小超过发送缓冲区大小，可能会跟别的报文合并发送，导致粘包</p><p>解决：</p><p>固定长度</p><p>分隔符</p><p>固定长度字段 + 内容</p><h2 id="netty的零拷贝机制" tabindex="-1"><a class="header-anchor" href="#netty的零拷贝机制"><span>Netty的零拷贝机制</span></a></h2><p><a href="https://www.mianshiya.com/bank/1804354610222800897/question/1804893517888823297" target="_blank" rel="noopener noreferrer">简单说说 Netty 的零拷贝机制？ - Netty 面试题 - 面试鸭 - 程序员求职面试刷题神器</a></p><p>避免在用户空间和内核之间拷贝数据，降低CPU和内存带宽的消耗</p>`,43)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};